head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
scwin.vScrenID = "ULDBNS90003.xml";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBndTpCd = '';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SetRowFocus
 * 설명       : 부모창에서 넘어온 채권유형에 따라 해당 위치를 설정한다.
 ***********************************************/
scwin.fn_SetRowFocus = function() {
    if (scwin.vBndTpCd == '') return;
    var firstData = '';
    //국채
    if (scwin.vBndTpCd == 'GB') {
        firstData = '111100'; //국고채권

    }
    //지방채
    else if (scwin.vBndTpCd == 'MB') {
        firstData = '112100'; //서울도시철도공채증권

    }
    //특수채
    else if (scwin.vBndTpCd == 'AB') {
        firstData = '113100'; //통화안정증권

    }
    //회사채
    else if (scwin.vBndTpCd == 'CO') {
        firstData = '116100'; //일반사채

    }
    //외국채
    else if (scwin.vBndTpCd == 'FO') {
        firstData = '130000'; //외국채권

    }
    var tempPos = $c.cp.getNameValueRow(dts_List, "BND_CLSS_CD", firstData);
    dts_List.setRowPosition(dts_List.getTotalRow(), 0);
    dts_List.setRowPosition(tempPos, 0);
};
scwin.dts_List_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (rowcount > 0) {
        scwin.fn_SetRowFocus();
    }
};
scwin.grd_List_OnDblClick = async function(row, colid) {
    if (row > 0) {
        var bndClssCd = dts_List.getCellData(dts_List.getRowPosition(), "BND_CLSS_CD");
        if (bndClssCd != '000000') {
            var showAlert = false;
            var tempStr = bndClssCd.substring(0, 3);
            //국채
            if (scwin.vBndTpCd == 'GB' && tempStr != '111') showAlert = true;
            //지방채


            else if (scwin.vBndTpCd == 'MB' && tempStr != '112') showAlert = true;
            //특수채


            else if (scwin.vBndTpCd == 'AB' && tempStr != '113') showAlert = true;
            //회사채


            else if (scwin.vBndTpCd == 'CO' && tempStr != '116') showAlert = true;
            //외국채


            else if (scwin.vBndTpCd == 'FO' && tempStr != '130') showAlert = true;
            if (showAlert) {
                if (!window.confirm('채권분류코드가 채권유형과 일치하지 않습니다.\n계속 진행하시겠습니까?')) return;
            }
        }
        var bndTpNm = dts_List.getCellData(dts_List.getRowPosition(), "BND_TP_NM");
        var arrPar = new Array();
        arrPar[0] = {
            BND_CLSS_CD: bndClssCd,
            BND_TP_NM: bndTpNm,
            BND_TP_NM1: bndClssCd + " " + bndTpNm
        };
        scwin.fn_SetPar(arrPar);
        await $c.frame.CloseFrame();
    }
};
scwin.img_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    //파라미터추출
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        var arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        if (typeof(arrPar[0].BND_TP_CD) != 'undefined') {
            scwin.vBndTpCd = arrPar[0].BND_TP_CD;
        }
        var url = "/listingCommon.do?method=listGeneralForDynamicName";
        url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
        url += "&outputMessageId=BNS_BND_CLSS";
        url += "&queryId=lds.stf.bnscommon.select.listBndClssCd";
        url += "&SCREN_ID=" + scwin.vScrenID;
        url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
        dts_List.DataID = encodeURI(url);
        dts_List.Reset();
    }
};
